179	fn walk_imports(body: &[parse::Stmt], out: &mut Vec<String>) {
180	    use parse::St;
181	    for s in body {
182	        match &s.st {
183	            St::Import(v) => {
184	                for (m, a) in v {
185	                    out.push(if a.is_some() { m.clone() } else { m.split('.').next().unwrap().to_string() });
186	                    // `import collections.abc` loads collections.abc too: Brevi's ABCs, not its typing forms
187	                    if a.is_none() && m == "collections.abc" {
188	                        out.push(m.clone());
189	                    }
190	                }
191	            }
192	            St::ImportFrom(m, _) => out.push(m.clone()),
193	            St::Def(d) => walk_imports(&d.body, out),
194	            St::Class(c) => walk_imports(&c.body, out),
195	            St::If(arms, els) => {
196	                for (c, b) in arms {
197	                    // `if TYPE_CHECKING:` imports are for type checkers (the block never runs)
198	                    if !typing::type_checking(c) {
199	                        walk_imports(b, out);
200	                    }
201	                }
202	                if let Some(b) = els {
203	                    walk_imports(b, out);
204	                }
205	            }
206	            St::For(_, _, b, e) | St::While(_, b, e) => {
207	                walk_imports(b, out);
208	                if let Some(e) = e {
209	                    walk_imports(e, out);
210	                }
211	            }
212	            St::Try(b, hs, e, f) => {
213	                walk_imports(b, out);
214	                for h in hs {
215	                    walk_imports(&h.body, out);
216	                }
217	                if let Some(e) = e {
218	                    walk_imports(e, out);
219	                }
220	                if let Some(f) = f {
221	                    walk_imports(f, out);
222	                }
223	            }
224	            St::With(_, b) => walk_imports(b, out),
225	            _ => {}
226	        }
227	    }
