463	// loaded first: asked of python3 when the program is built, without importing duckdb.
464	fn duck_libs() -> (Vec<String>, String) {
465	    const Q: &str = "import importlib.util, glob, os, sys, sysconfig\ns = importlib.util.find_spec('duckdb')\nd = os.path.dirname(list(s.submodule_search_locations)[0]) if s and s.submodule_search_locations else ''\nlibs = sorted(glob.glob(os.path.join(d, '_duckdb*.so')) + glob.glob(os.path.join(d, '*duckdb*.dll')) + glob.glob(os.path.join(d, '_duckdb*.pyd'))) if d else []\nlib = os.path.join(sys.base_prefix, 'python%d%d.dll' % sys.version_info[:2]) if os.name == 'nt' else os.path.join(sysconfig.get_config_var('LIBDIR') or '', sysconfig.get_config_var('INSTSONAME') or sysconfig.get_config_var('LDLIBRARY') or '')\nprint('\\x01'.join([lib] + libs))";
466	    let exe = crate::python_exe();
467	    let out = std::process::Command::new(&exe).args(["-c", Q]).output().map(|o| String::from_utf8_lossy(&o.stdout).trim_end().to_string()).unwrap_or_default();
468	    let mut parts = out.split('\u{1}').map(String::from);
469	    let pre = parts.next().unwrap_or_default();
470	    (parts.filter(|x| !x.is_empty()).collect(), pre)
471	}
