from collections.abc import MutableMapping
class W(MutableMapping):
    def __init__(self):
        self.data = {'a': 1}
        self.extra = [2]
    def __getitem__(self, k):
        return self.data[k]
    def __setitem__(self, k, v):
        self.data[k] = v
    def __delitem__(self, k):
        del self.data[k]
    def __iter__(self):
        return iter(self.data)
    def __len__(self):
        return len(self.data)
    def __copy__(self):
        inst = object.__new__(self.__class__)
        inst.__dict__.update(self.__dict__)
        inst.__dict__["data"] = self.__dict__["data"].copy()
        return inst

import copy
w = W()
v = copy.copy(w)
print(v.data is w.data, v.data == w.data, v.extra is w.extra)
print(isinstance(v, MutableMapping))

